-- More categories (user request 2026-11-21). All are YouTube-sourced (categories.source = 'youtube'):
-- found and counted by the YouTube Data API (~400 quota units each per day, 10,000 free), so they
-- don't use Brave credit (Brave already at ~750 of ~1,000 requests/month).
-- match = must be a Thai ad (Thai script / thai / th) AND mention this category's brand in the
-- title or channel (the official-channel check unions every category's brands, so a Shopee search
-- could otherwise keep an AIS ad).
insert into public.categories (id, name_th, name_en, emoji, query, sort_order, match, brands, source) values
  ('shopping', 'ช้อปปิ้งและค้าปลีก', 'Shopping', '🛒', 'Shopee Thailand โฆษณา; Lazada Thailand โฆษณา; Lotus''s โฆษณา; Big C โฆษณา', 8, '^(?=.*([ก-๙]|thai|\bth\b))(?=.*(shopee|ช้อปปี้|lazada|ลาซาด้า|lotus''?s|โลตัส|\bbig ?c\b|บิ๊กซี|\bmakro\b|แม็คโคร|central ?(group|department|online|thailand)|เซ็นทรัล|robinson|tops ?(thailand|market)|\bthe ?mall\b))', 'shopee|ช้อปปี้|lazada|ลาซาด้า|lotus''?s|โลตัส|\bbig ?c\b|บิ๊กซี|\bmakro\b|แม็คโคร|central ?(group|department|online|thailand)|เซ็นทรัล|robinson|tops ?(thailand|market)|\bthe ?mall\b', 'youtube'),
  ('apps', 'แอปและเดลิเวอรี่', 'Apps & Delivery', '🛵', 'Grab Thailand โฆษณา; LINE MAN โฆษณา; foodpanda Thailand โฆษณา; LINE Thailand โฆษณา', 9, '^(?=.*([ก-๙]|thai|\bth\b))(?=.*(\bgrab\b|แกร็บ|line ?man|ไลน์แมน|foodpanda|ฟู้ดแพนด้า|robinhood ?(app|thailand)|line ?thailand|\bline ?th\b|wongnai|วงใน|\bbolt ?thailand))', '\bgrab\b|แกร็บ|line ?man|ไลน์แมน|foodpanda|ฟู้ดแพนด้า|robinhood ?(app|thailand)|line ?thailand|\bline ?th\b|wongnai|วงใน|\bbolt ?thailand', 'youtube'),
  ('travel', 'ท่องเที่ยวและสายการบิน', 'Travel', '✈️', 'AirAsia Thailand โฆษณา; Thai Airways โฆษณา; ททท Amazing Thailand โฆษณา; Agoda โฆษณา', 10, '^(?=.*([ก-๙]|thai|\bth\b))(?=.*(air ?asia|แอร์เอเชีย|thai ?airways|การบินไทย|nok ?air|นกแอร์|bangkok ?airways|บางกอกแอร์เวย์ส|thai ?lion|thai ?vietjet|amazing ?thailand|tourism ?authority|การท่องเที่ยวแห่งประเทศไทย|\btat\b|agoda|อโกด้า|traveloka))', 'air ?asia|แอร์เอเชีย|thai ?airways|การบินไทย|nok ?air|นกแอร์|bangkok ?airways|บางกอกแอร์เวย์ส|thai ?lion|thai ?vietjet|amazing ?thailand|tourism ?authority|การท่องเที่ยวแห่งประเทศไทย|\btat\b|agoda|อโกด้า|traveloka', 'youtube'),
  ('home', 'บ้านและอสังหา', 'Home & Property', '🏠', 'SCG โฆษณา; แสนสิริ โฆษณา; AP Thailand โฆษณา; HomePro โฆษณา', 11, '^(?=.*([ก-๙]|thai|\bth\b))(?=.*(\bscg\b|sansiri|แสนสิริ|\bap ?thailand\b|land ?(and|&) ?houses|แลนด์ ?แอนด์ ?เฮ้าส์|pruksa|พฤกษา|supalai|ศุภาลัย|homepro|โฮมโปร|index ?living|อินเด็กซ์|thai ?watsadu|ไทวัสดุ|global ?house|toa ?paint|\btoa\b))', '\bscg\b|sansiri|แสนสิริ|\bap ?thailand\b|land ?(and|&) ?houses|แลนด์ ?แอนด์ ?เฮ้าส์|pruksa|พฤกษา|supalai|ศุภาลัย|homepro|โฮมโปร|index ?living|อินเด็กซ์|thai ?watsadu|ไทวัสดุ|global ?house|toa ?paint|\btoa\b', 'youtube'),
  ('health', 'สุขภาพ', 'Health', '💊', 'BRAND''S Thailand โฆษณา; โรงพยาบาลกรุงเทพ โฆษณา; Tiffy โฆษณา; Sara Thailand โฆษณา', 12, '^(?=.*([ก-๙]|thai|\bth\b))(?=.*(brand''?s ?(thailand|suntory|essence)|แบรนด์ซุปไก่|bangkok ?hospital|โรงพยาบาลกรุงเทพ|bumrungrad|บำรุงราษฎร์|samitivej|สมิติเวช|\bbdms\b|tiffy|ทิฟฟี่|sara ?thailand|ซาร่า|\bblackmores\b|mega ?we ?care|เมก้า ?วี ?แคร์|vistra|วิสทร้า|counterpain|เคาน์เตอร์เพน))', 'brand''?s ?(thailand|suntory|essence)|แบรนด์ซุปไก่|bangkok ?hospital|โรงพยาบาลกรุงเทพ|bumrungrad|บำรุงราษฎร์|samitivej|สมิติเวช|\bbdms\b|tiffy|ทิฟฟี่|sara ?thailand|ซาร่า|\bblackmores\b|mega ?we ?care|เมก้า ?วี ?แคร์|vistra|วิสทร้า|counterpain|เคาน์เตอร์เพน', 'youtube')
on conflict (id) do update set name_th = excluded.name_th, name_en = excluded.name_en, emoji = excluded.emoji,
  query = excluded.query, sort_order = excluded.sort_order, match = excluded.match, brands = excluded.brands,
  source = excluded.source;

update public.categories set sort_order = 13 where id = 'youtube';
